'use strict';
const fs=require('fs'),path=require('path'),crypto=require('crypto'),cp=require('child_process');
const root=path.resolve(__dirname,'..');
const wrapper=path.join(root,'SMARTER_JUSTICE__ONE_FILE_GITHUB_UPLOAD__PRE117.zip');
const runtimeName='SMARTER_JUSTICE__PRE117_DEPLOY_RUNTIME.tgz';
const extracted=path.join(root,'.runtime',runtimeName);
const target=path.join(root,'.runtime','pre117-live');
const sha=f=>crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex');
const fail=m=>{console.error('[PRE117 DEPLOY] '+m);process.exit(1)};
const ok=(v,m)=>{if(!v)fail(m)};
ok(fs.existsSync(wrapper),'PRE117 wrapper missing');
ok(fs.statSync(wrapper).size===14153144,'wrapper size mismatch');
ok(sha(wrapper)==='6e66a8580f075f47c9f029119ac0df04e337a7bd0cead639081bc99ca631872e','wrapper hash mismatch');
fs.mkdirSync(path.dirname(extracted),{recursive:true});
const py=`import pathlib,sys,zipfile\nsrc=pathlib.Path(sys.argv[1]);out=pathlib.Path(sys.argv[2]);name=${JSON.stringify(runtimeName)}\nwith zipfile.ZipFile(src) as z:\n assert z.namelist()==[name]\n out.write_bytes(z.read(name))`;
let q=cp.spawnSync(process.env.PYTHON_BIN||'python3',['-c',py,wrapper,extracted],{encoding:'utf8'});if(q.status!==0)fail(q.stderr||q.stdout);
ok(fs.statSync(extracted).size===14152962,'runtime size mismatch');
ok(sha(extracted)==='2f1af991887ba4963ef0570ae3da913bdbe34972be5f3fae4164515bc16a20f8','runtime hash mismatch');
const names=cp.execFileSync('tar',['-tzf',extracted],{encoding:'utf8',maxBuffer:128*1024*1024});
for(const raw of names.split(/\r?\n/)){const n=raw.trim().replace(/^\.\//,'');if(!n)continue;ok(!path.posix.isAbsolute(n)&&!n.split('/').includes('..'),'unsafe archive path '+n)}
fs.rmSync(target,{recursive:true,force:true});fs.mkdirSync(target,{recursive:true});cp.execFileSync('tar',['-xzf',extracted,'-C',target],{stdio:'inherit'});
let count=0;const walk=d=>{for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(e.isFile())count++}};walk(target);ok(count===4418,'runtime file count mismatch: '+count);
const read=r=>JSON.parse(fs.readFileSync(path.join(target,r),'utf8'));
const p=read('package.json');ok(p.version==='2.0.0-pre117','runtime version mismatch');
const receipt=read('coordination/pre117/FINAL_QUALIFICATION_RECEIPT.json');
ok(receipt.status==='PASS_QUALIFIED_NONPRODUCTION','qualification mismatch');
ok(receipt.targetedChecks===127&&receipt.featureRuntimeChecks===11&&receipt.regressionChecks===267,'qualification count mismatch');
ok(receipt.sameOriginLinks===6555&&receipt.secretScanHighConfidenceFindings===0,'integrity qualification mismatch');
ok(receipt.noLoss.missing===0&&receipt.noLoss.unauthorizedChanged===0,'no-loss mismatch');
ok(receipt.controlledOfficialPdfLanes===12,'form-lane mismatch');
for(const f of ['server.js','lib/formEnginePre117.js','lib/acquisitionRevenuePre117.js','lib/coordinationPre117.js','lib/productPaymentEvidencePre117.js','lib/deadlineEvidencePre117.js','data/moduleImprovementPre117.js','data/nyLegalSourcePacksPre117.js']) cp.execFileSync(process.execPath,['--check',path.join(target,f)],{stdio:'inherit'});
const marker={schemaVersion:'smarter-justice.pre117.render-bootstrap.direct.v1',release:'v2.0.0-pre117',qualificationStatus:'QUALIFIED_NONPRODUCTION',carrierSha256:'6e66a8580f075f47c9f029119ac0df04e337a7bd0cead639081bc99ca631872e',runtimeArchiveSha256:'2f1af991887ba4963ef0570ae3da913bdbe34972be5f3fae4164515bc16a20f8',runtimeFiles:4418,sccc:'v0.15.0/SCCC15.0',coordinationStandard:'UEC-1.13',revenueEngineDonor:'v0.8.0',attorneyProfileFactoryAuthority:'F50',f51State:'RECOVERY_SAFE_CANDIDATE_OFFLINE_ONLY',controlledGenerationLanes:12,productionAuthorization:false,preparedAt:new Date().toISOString()};
fs.writeFileSync(path.join(target,'.pre117-render-bootstrap.json'),JSON.stringify(marker,null,2)+'\n');
console.log('[PRE117 DEPLOY] exact qualified runtime extracted; live-effects remain product-gated');
